  (() => {
    const text = (
      ($json.Subject || '') + ' ' +
      ($json.snippet || '') + ' ' +
      ($json.From || '')
    ).toLowerCase();

    // Strong recruitment/application signals.
    const jobSignals = [
      'application',
      'applied',
      'candidate',
      'candidacy',
      'interview',
      'assessment',
      'technical round',
      'technical interview',
      'screening',
      'shortlisted',
      'shortlist',
