      'recruitment',
      'hiring',
      'selection',
      'selected',
      'next step',
      'next steps',
      'next stage',
      'job opportunity',
      'employment',
      'position',
      'role',
      'career',
      'careers',
      'onboarding',
      'job offer'
    ];

    // Obvious job-alert/newsletter patterns.
      const jobAlerts = [
        'jobmail',
        'job alert',
        'jobs that match',
        'job recommendations',
        'new jobs',
        'new job',
        'new internship',
        'internship job',
        'job in remote',
        'jobs in remote',
        'more new jobs',
        'job matches',
        'jobs matching',
        'matches for you',
        'apply now',
        'saved jobs',
        'job digest',
        'career digest',
        'weekly jobs',
        'daily jobs',
        'connections',
        'messaged you'
      ];
    // Obvious non-job emails.
    const nonJobSignals = [
      'newsletter',
      'subscription',
      'subscribe',
      'unsubscribe',
      'promotion',
      'promotional',
      'discount',
      'sale',
      'limited time',
      'order confirmation',
      'order delivered',
      'delivery update',
      'payment',
      'invoice',
      'transaction',
      'otp',
      'one time password',
      'verify your email',
      'verify your account',
      'activate your account'
    ];

    const hasJobSignal = jobSignals.some(word =>
      text.includes(word)
    );

    const isJobAlert = jobAlerts.some(word =>
      text.includes(word)
    );

    const isObviousNonJob = nonJobSignals.some(word =>
      text.includes(word)
    );

    // Strong application confirmations always pass.
    const isApplicationConfirmation =
      text.includes('application received') ||
      text.includes('application submitted') ||
      text.includes('application was sent') ||
      text.includes('thank you for applying') ||
      text.includes('thank you for your application') ||
      text.includes('we received your application') ||
      text.includes('successfully applied');

    if (isApplicationConfirmation) {
      return true;
    }

    // Obvious shopping/newsletter/account emails stop here.
    if (isObviousNonJob) {
      return false;
    }

    // Job alerts are normally not applications.
    if (isJobAlert) {
      return false;
    }

    // Everything else that looks potentially recruitment-related
    // is sent to Gemini for the final classification.
    return hasJobSignal;
  })()
}}

