const raw =
  $json.content?.parts?.[0]?.text ??
  $json.text ??
  $json.output ??
  $json.response ??
  $json;

let ai;

if (raw && typeof raw === 'object' && !Array.isArray(raw) && raw.type) {
  ai = raw;
} else {
  const text = String(raw ?? '')
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  try {
    ai = JSON.parse(text);
  } catch (error) {
    return {
      json: {
        type: 'NOT_JOB_RELATED',
        company: '',
        position: '',
        source: '',
        status: '',
        appliedDate: '',
        jobUrl: '',
        emailSubject: $('Edit Fields').item.json.emailSubject ?? '',
        emailBody: $('Edit Fields').item.json.emailBody ?? '',
        emailHtml: $('Edit Fields').item.json.emailHtml ?? '',
        sender: $('Edit Fields').item.json.sender ?? '',
        emailDate: $('Edit Fields').item.json.emailDate ?? '',
        gmailMessageId: $('Edit Fields').item.json.gmailMessageId ?? '',
        gmailThreadId: $('Edit Fields').item.json.gmailThreadId ?? '',
        parseError: true,
        parseErrorMessage: error.message,
        rawAIResponse: text,
      }
    };
  }
}

const email = $('Edit Fields').item.json;

return {
  json: {
    type: String(ai.type ?? '').trim(),
    company: String(ai.company ?? '').trim(),
    position: String(ai.position ?? '').trim(),
    source: String(ai.source ?? '').trim(),
    status: String(ai.status ?? '').trim(),
    appliedDate: String(ai.appliedDate ?? '').trim(),
    jobUrl: String(ai.jobUrl ?? '').trim(),
    emailSubject: email.emailSubject ?? '',
    emailBody: email.emailBody ?? '',
    emailHtml: email.emailHtml ?? '',
    sender: email.sender ?? '',
    emailDate: email.emailDate ?? '',
    gmailMessageId: email.gmailMessageId ?? '',
    gmailThreadId: email.gmailThreadId ?? '',
  }
};

const incoming = $json;
const rows = $('Read Tracker Rows').all().map(item => item.json);

const norm = (v) => String(v ?? '')
  .trim()
  .toLowerCase()
  .replace(/\s+/g, ' ');

const normUrl = (v) => norm(v).replace(/^https?:\/\//, '').replace(/\/+$/, '');

const company = norm(incoming.company);
const position = norm(incoming.position);
const jobUrl = normUrl(incoming.jobUrl);

// Ignore malformed/non-job AI results before touching the sheet.
const type = String(incoming.type ?? '').trim();
if (!['NEW_APPLICATION', 'APPLICATION_UPDATE'].includes(type)) {
  return { json: { action: 'skip', reason: 'not_job_related_or_invalid_ai', ...incoming } };
}

// A useful identity is URL when available, otherwise company + position.
// Gmail IDs are deliberately not used because they aren't stored in your 8-column sheet.
const incomingKey = jobUrl
  ? `url|${jobUrl}`
  : (company && position ? `job|${company}|${position}` : '');

if (!incomingKey) {
  return { json: { action: 'skip', reason: 'missing_company_position_and_url', ...incoming } };
}

let existing = null;
let existingRowNumber = 0;

for (const row of rows) {
  const rowCompany = norm(row.Company);
  const rowPosition = norm(row.Position);
  const rowUrl = normUrl(row['Job URL']);

  const sameUrl = jobUrl && rowUrl && jobUrl === rowUrl;
  const sameCompanyPosition = company && position &&
    company === rowCompany && position === rowPosition;

  if (sameUrl || sameCompanyPosition) {
    const rn = Number(row.row_number || 0);
    if (!existing || rn > existingRowNumber) {
      existing = row;
      existingRowNumber = rn;
    }
  }
}

const statusRank = (value) => {
  const s = norm(value);
  if (!s) return 0;
  if (s.includes('withdraw')) return 6;
  if (s.includes('reject')) return 6;
  if (s.includes('offer')) return 6;
  if (s.includes('hired')) return 7;
  if (s.includes('assessment') || s.includes('screen')) return 2;
  if (s.includes('interview')) return 4;
  if (s.includes('shortlist')) return 3;
  if (s.includes('applied') || s.includes('submitted') || s.includes('received')) return 1;
  return 1;
};

const incomingStatus = String(incoming.status ?? '').trim();
const existingStatus = String(existing?.Status ?? '').trim();

const base = {
  Company: String(incoming.company ?? '').trim(),
  Position: String(incoming.position ?? '').trim(),
  Source: String(incoming.source ?? '').trim(),
  'Applied Date': String(incoming.appliedDate ?? '').trim(),
  Status: incomingStatus || 'Applied',
  'Job URL': String(incoming.jobUrl ?? '').trim(),
  'Email Subject': String(incoming.emailSubject ?? '').trim(),
  Notes: String(incoming.emailBody ?? '').trim(),
};

if (!existing) {
  if (type === 'APPLICATION_UPDATE') {
    return { json: { action: 'skip', reason: 'update_without_existing_application', ...incoming } };
  }

  return {
    json: {
      action: 'append',
      ...base,
    }
  };
}

// NEW_APPLICATION for an already-known job is a duplicate. Never overwrite a later status.
if (type === 'NEW_APPLICATION') {
  return {
    json: {
      action: 'skip',
      reason: 'duplicate_application',
      row_number: existingRowNumber,
      existingStatus,
      ...incoming,
    }
  };
}

// APPLICATION_UPDATE: update only if the new status is meaningful and does not regress the row.
const oldRank = statusRank(existingStatus);
const newRank = statusRank(incomingStatus);

if (!incomingStatus || newRank < oldRank) {
  return {
    json: {
      action: 'skip',
      reason: 'empty_or_regressive_status',
      row_number: existingRowNumber,
      existingStatus,
      incomingStatus,
      ...incoming,
    }
  };
}

const oldNotes = String(existing.Notes ?? '').trim();
const updateNote = [
  incoming.emailSubject ? `Update: ${incoming.emailSubject}` : '',
  incoming.emailBody ? incoming.emailBody : ''
].filter(Boolean).join('\n');

const mergedNotes = updateNote
  ? (oldNotes ? `${oldNotes}\n\n${updateNote}` : updateNote)
  : oldNotes;

return {
  json: {
    action: 'update',
    row_number: existingRowNumber,
    Company: String(incoming.company ?? '').trim() || String(existing.Company ?? ''),
    Position: String(incoming.position ?? '').trim() || String(existing.Position ?? ''),
    Source: String(incoming.source ?? '').trim() || String(existing.Source ?? ''),
    'Applied Date': String(incoming.appliedDate ?? '').trim() || String(existing['Applied Date'] ?? ''),
    Status: incomingStatus,
    'Job URL': String(incoming.jobUrl ?? '').trim() || String(existing['Job URL'] ?? ''),
    'Email Subject': String(incoming.emailSubject ?? '').trim() || String(existing['Email Subject'] ?? ''),
    Notes: mergedNotes,
  }
};
